WITH target AS (
  SELECT raceId FROM races WHERE name = 'Australian Grand Prix' AND year = 2008 LIMIT 1
), finished AS (
  SELECT * FROM results WHERE raceId = (SELECT raceId FROM target) AND time IS NOT NULL
), winner AS (
  SELECT milliseconds AS w_ms FROM finished WHERE positionOrder = 1 LIMIT 1
), lastfin AS (
  SELECT milliseconds AS l_ms FROM finished WHERE positionOrder = (SELECT MAX(positionOrder) FROM finished) LIMIT 1
)
SELECT ((lastfin.l_ms - winner.w_ms) * 100.0) / lastfin.l_ms AS percentage
FROM winner, lastfin;

WITH final_race AS (
  SELECT MAX(raceId) AS raceId FROM races WHERE year = 2009
), champ AS (
  SELECT driverId FROM driverStandings WHERE position = 1 AND raceId = (SELECT raceId FROM final_race)
), races2009 AS (
  SELECT raceId FROM races WHERE year = 2009
), minmill AS (
  SELECT MIN(milliseconds) AS m FROM lapTimes
  WHERE driverId = (SELECT driverId FROM champ) AND raceId IN (SELECT raceId FROM races2009)
)
SELECT lap FROM lapTimes
WHERE driverId = (SELECT driverId FROM champ)
  AND raceId IN (SELECT raceId FROM races2009)
  AND milliseconds = (SELECT m FROM minmill)
LIMIT 1;
